"""Default-off production preview boundary; no broker or order transport."""
import os
from fastapi import HTTPException, Request
from fastapi.responses import HTMLResponse

PREVIEW_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BXK Trade Workbench</title><link rel="stylesheet" href="/static/workbench-preview.css?v=1"></head>\n<body><main class="workbench">\n<header><div><p class="eyebrow">BXK TRADER PRO</p><h1>Trade Workbench</h1><p class="subtitle">Explore SPXW iron condors using your verified broker connection.</p></div><a class="back-link" href="/">Back to dashboard</a></header>\n<div class="notice"><strong>Owner preview · Analysis and dry-run only</strong><span>Order submission is unavailable. Quotes are snapshots; prices, risk and buying power are checked again during review.</span></div>\n<section class="panel"><div class="section-heading"><span class="step">1</span><div><h2>Market data</h2><p>Check your connection, then choose an expiration and strike range.</p></div></div>\n<button type="button" id="checkConnection">Check my SPXW expirations</button><p id="connectionStatus" role="status"></p>\n<details><summary>Available expirations</summary><ul id="expirationList" class="expiration-list"></ul></details>\n<div class="field-grid"><label>Expiration<select id="quoteExpiry"></select></label><label>Minimum strike<input id="quoteMin" type="number" min="1" step="5" placeholder="e.g. 7600"></label><label>Maximum strike<input id="quoteMax" type="number" min="1" step="5" placeholder="e.g. 7880"></label><button id="loadQuotes" type="button" disabled>Load bid/ask quotes</button></div>\n<p id="quoteStatus" role="status"></p><details><summary>Quote snapshot details</summary><div id="quoteResults" class="table-scroll"></div></details></section>\n<section class="panel"><div class="section-heading"><span class="step">2</span><div><h2>Combined condor analysis</h2><p>SPX and expected move fill automatically from fresh broker quotes.</p></div></div>\n<div class="field-grid analysis-fields"><label>SPX reference<input id="analysisSpot" type="number" min="1" step="0.01" readonly></label><label>Expected move (1σ points)<input id="analysisMove" type="number" min="0.01" step="0.01" readonly></label><label>Wing width (points)<input id="analysisWidth" type="number" min="1" max="100" value="10"></label><label>Minimum modeled POP (%)<input id="analysisPop" type="number" min="1" max="99" value="70"></label></div>\n<p class="help">Modeled POP uses a normal-distribution approximation, not broker POP. Credits and maximum losses exclude fees until broker review.</p><button id="analyzeCondors" type="button">Analyze condors</button><p id="analysisStatus" role="status"></p><div id="analysisResults" class="table-scroll"></div></section>\n<footer>Review all four legs before checking broker risk and buying power. No live order can be submitted from this workbench.</footer>\n<script src="/static/workbench-preview.js?v=4" defer></script></main></body></html>'

def workbench_page(request: Request):
    if os.getenv("BXK_WORKBENCH_PREVIEW_ENABLED", "").strip().lower() != "true":
        raise HTTPException(404, "Not found")
    from bxk_app.authorization import require_owner
    require_owner(request)
    return HTMLResponse(PREVIEW_HTML, headers={
        "Cache-Control": "no-store", "X-Robots-Tag": "noindex, nofollow",
        "Content-Security-Policy": "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'; form-action 'none'; frame-ancestors 'none'",
    })
